UPDATE [Выбросы ЗВ] AS ZV SET ZV.VIBROS_ekol = IIf(ZV.VIBROS_ekol Is Null,0,ZV.VIBROS_ekol), ZV.TVERD_V = IIf(ZV.TVERD_V Is Null,0,ZV.TVERD_V), ZV.[GAZ and ZHID] = IIf(ZV.[GAZ and ZHID] Is Null,0,ZV.[GAZ and ZHID]), ZV.SO2_gaz = IIf(ZV.SO2_gaz Is Null,0,ZV.SO2_gaz), ZV.CO_gaz = IIf(ZV.CO_gaz Is Null,0,ZV.CO_gaz), ZV.NOx_gaz = IIf(ZV.NOx_gaz Is Null,0,ZV.NOx_gaz), ZV.UGLEVOD = IIf(ZV.UGLEVOD Is Null,0,ZV.UGLEVOD), ZV.LOS = IIf(ZV.LOS Is Null,0,ZV.LOS), ZV.PROCH_ekol = IIf(ZV.PROCH_ekol Is Null,0,ZV.PROCH_ekol)
WHERE ((ZV.VIBROS_ekol Is Null) OR (ZV.TVERD_V Is Null) OR (ZV.[GAZ and ZHID] Is Null) Or (ZV.SO2_gaz Is Null) Or (ZV.CO_gaz Is Null) OR (ZV.NOx_gaz Is Null) OR (ZV.UGLEVOD Is Null) Or (ZV.LOS Is Null) OR (ZV.PROCH_ekol Is Null));
